create table coupon
(
    discount_value       decimal(15, 2)              null,
    max_usage            int                         null,
    used_count           int                         not null,
    applicable_course_id bigint                      null,
    created_at           datetime(6)                 not null,
    created_by           bigint                      null,
    id                   bigint                      not null
        primary key,
    updated_at           datetime(6)                 null,
    updated_by           bigint                      null,
    valid_from           datetime(6)                 null,
    valid_to             datetime(6)                 null,
    code                 varchar(50)                 not null,
    discount_type        enum ('FIXED', 'PERCENT')   null,
    status               enum ('ACTIVE', 'INACTIVE') not null,
    constraint idx_coupon_code
        unique (code),
    constraint FKj4qx7bfui588m2wanb6gynp98
        foreign key (applicable_course_id) references course (id)
);

